function I(t,n){if(!t||t.type==="linear")return n;switch(t.type){case"easeIn":return n*n*n;case"easeOut":return 1-Math.pow(1-n,3);case"easeInOut":return n<.5?4*n*n*n:1-Math.pow(-2*n+2,3)/2;case"bezier":return O(t.x1??.4,t.y1??0,t.x2??.6,t.y2??1,n);default:return n}}function O(t,n,o,e,r){const a=3*t,u=3*(o-t)-a,f=1-a-u,s=3*n,d=3*(e-n)-s,b=1-s-d,h=c=>((f*c+u)*c+a)*c,l=c=>((b*c+d)*c+s)*c,x=c=>(3*f*c+2*u)*c+a;let i=r;for(let c=0;c<8;c++){const y=h(i)-r;if(Math.abs(y)<1e-6)return l(i);const v=x(i);if(Math.abs(v)<1e-6)break;i-=y/v}let k=0,M=1;for(i=r;M-k>1e-6;)h(i)<r?k=i:M=i,i=(k+M)/2;return l(i)}function p(){return{type:"easeInOut"}}function g(t,n){if(!t||t.length===0)return 0;if(n<=t[0].t)return t[0].v;const o=t[t.length-1];if(n>=o.t)return o.v;for(let e=0;e<t.length-1;e++){const r=t[e],a=t[e+1];if(n>=r.t&&n<=a.t){const u=a.t-r.t,f=u>1e-9?(n-r.t)/u:0,s=I(r.ease,f);return r.v+(a.v-r.v)*s}}return o.v}function m(t,n){const o={};for(const e of Object.keys(t.tracks))o[e]=g(t.tracks[e],n);return o}function j(t,n,o){let e=(n-t)%(Math.PI*2);return e>Math.PI&&(e-=Math.PI*2),e<-Math.PI&&(e+=Math.PI*2),t+e*o}function P(t,n,o,e){const r=t.duration>0?o/t.duration%1:0,a=n.duration>0?o/n.duration%1:0,u=m(t,r*t.duration),f=m(n,a*n.duration),s=new Set([...Object.keys(u),...Object.keys(f)]),d={};for(const b of s){const h=u[b]??0,l=f[b]??0;d[b]=b==="root.x"||b==="root.y"?h*(1-e)+l*e:j(h,l,e)}return d}function w(t,n,o,e,r){const a=Math.max(t.duration,n.duration),u=Math.max(2,Math.round(a*e)),f=new Set([...Object.keys(t.tracks),...Object.keys(n.tracks)]);r.duration=a,r.tracks={};for(const s of f)r.tracks[s]=[];for(let s=0;s<=u;s++){const d=s/u*a,b=P(t,n,d,o);for(const h of f)r.tracks[h].push({t:d,v:b[h]??0,ease:{type:"linear"}})}return r}export{P as a,w as b,p as d,m as s};
